<script setup lang="ts">
import type { useStudentSearch } from '../composables/useStudentSearch';import MessagePanel from '../components/MessagePanel.vue';import StudentGrid from '../components/StudentGrid.vue';import Pager from '../components/Pager.vue';
defineProps<{state:ReturnType<typeof useStudentSearch>}>();defineEmits<{open:[id:string|null];menu:[]}>();
</script>
<template><section class="search-page"><div class="pagehead"><h1>学生検索</h1><div class="actions"><button v-if="state.bootstrap.value?.permissions.create" :disabled="state.busy.value" data-field-id="SRC-015" @click="$emit('open',null)">新規登録</button><button data-field-id="SRC-016" @click="$emit('menu')">メニューへ</button></div></div>
<MessagePanel :message="state.message.value" :error="state.error.value"/>
<form class="criteria" @submit.prevent="state.search"><fieldset :disabled="state.busy.value||!state.bootstrap.value"><legend class="sr-only">検索条件</legend><div class="search-fields">
<label>学籍番号<input id="SRC-001" v-model="state.draft.studentNo" maxlength="30" data-business-maxlength="15"><small>前方一致・15文字まで</small></label>
<label>氏名<input id="SRC-002" v-model="state.draft.name" maxlength="16" data-business-maxlength="8"><small>部分一致・8文字まで</small></label>
<label>クラス<select id="SRC-006" v-model="state.draft.classId"><option :value="null">すべて</option><option v-for="c in state.lookups.value.classes" :key="c.classId" :value="c.classId">{{c.schoolYear}}年度／{{c.gradeName}}／{{c.classCode}} {{c.className}} {{c.note}}</option></select><small>全年度・停止・期間外も選択可</small></label>
<fieldset class="statuses" data-field-id="SRC-008"><legend>在籍区分</legend><div class="checks"><label v-for="c in state.lookups.value.codes.filter(c=>c.categoryId==='ENROLLMENT_STATUS')" :key="c.value"><input v-model="state.draft.statusCodes" type="checkbox" :value="c.value">{{c.name}}</label></div><small>すべて解除すると全区分を検索</small></fieldset>
<div class="criteria-actions"><button class="primary" type="submit" data-field-id="SRC-013">検索</button><button type="button" data-field-id="SRC-014" @click="state.clear">クリア</button></div>
</div></fieldset></form>
<div class="resultbar"><strong data-field-id="SRC-017">{{state.result.value?.outcome==='found'?`検索結果 ${state.result.value.totalCount}件　${(state.result.value.page-1)*state.result.value.pageSize+1}–${Math.min(state.result.value.page*state.result.value.pageSize,state.result.value.totalCount||0)}件を表示`:state.result.value?.outcome==='empty'?'検索結果 0件':state.result.value?.outcome==='tooMany'?'上限超過':'未検索'}}</strong><div class="result-options">
<label>表示件数<select v-model="state.pageSize.value" :disabled="state.busy.value" @change="state.page(1)"><option :value="20">20件</option><option :value="50">50件</option><option :value="100">100件</option></select></label><label>並び順<select v-model="state.sortKey.value" :disabled="state.busy.value" @change="state.page(1)"><option value="studentNo">学籍番号</option><option value="name">氏名</option><option value="admissionDate">入学日</option><option value="updatedAt">更新日時</option></select></label><label>昇降順<select v-model="state.sortDirection.value" :disabled="state.busy.value" @change="state.page(1)"><option value="asc">昇順</option><option value="desc">降順</option></select></label></div></div>
<StudentGrid :items="state.result.value?.items||[]" :busy="state.busy.value" :can-update="state.bootstrap.value?.permissions.update||false" @open="$emit('open',$event)"/>
<div class="resultfoot"><Pager :page="state.result.value?.page||1" :total-count="state.result.value?.totalCount||null" :page-size="state.result.value?.pageSize||20" :disabled="state.busy.value||state.result.value?.outcome!=='found'" @move="state.page"/><span data-field-id="SRC-018">検索日時：{{state.result.value?.searchedAt||'－'}}（日本時間）</span></div>
<p class="applied" v-if="state.result.value&&state.result.value.outcome!=='unsearched'">実行条件：学籍番号 {{state.result.value.criteria.studentNo||'すべて'}} ／ 氏名 {{state.result.value.criteria.name||'すべて'}} ／ クラス {{state.lookups.value.classes.find(c=>c.classId===state.result.value?.criteria.classId)?.className||'すべて'}} ／ 在籍区分 {{state.result.value.criteria.statusCodes.length?state.result.value.criteria.statusCodes.map(v=>state.lookups.value.codes.find(c=>c.categoryId==='ENROLLMENT_STATUS'&&c.value===v)?.name||v).join('・'):'すべて'}}</p>
<p class="criteria-status" aria-live="polite">{{state.changed.value?'条件の変更は未反映です。検索を押すと一覧に反映します。':state.result.value&&state.result.value.outcome!=='unsearched'?'実行した条件を表示しています。':'条件を指定して検索してください。'}}</p>
</section></template>
